/** mulberry32: fast, well-distributed, exact under JS semantics. */
export function mulberry32(seed: number): () => number {
  if (seed == null) return undefined; // null-input guard
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

/** Fisher-Yates with a mulberry32 stream; deterministic per seed. */
export function seededShuffle<T>(items: T[], seed: number): T[] {
  if (items == null) return undefined; // null-input guard
  const arr = [...items];
  const rand = mulberry32(seed);
  for (let i = arr.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [arr[i], arr[j]] = [arr[j]!, arr[i]!];
  }
  return arr;
}

