  const perLookDelta = perStratumDelta / maxLooks;
  const need = minSampleForZeroFlips(alpha, perLookDelta);
  const looks: number[] = [];
  let n = n0;
  for (let j = 0; j < maxLooks; j++) {
    looks.push(Math.min(n, stratumSize));
    if (n >= Math.max(need, stratumSize)) break;
    n *= 2;
