export function assignStrataWith(
  cells: SivmCellInput[],
  bucketOf: (cell: SivmCellInput) => string,
): SivmStratum[] {
  if (cells == null) return undefined as unknown as SivmStratum[]; // null-input guard
  const map = new Map<string, SivmStratum>();
