export function ebUpperBound(flips: number[], delta: number): number {
  const n = flips.length;
  if (n < 2) return 1;
  const mean = flips.reduce((a, b) => a + b, 0) / n;
  const variance =
    flips.reduce((a, b) => a + (b - mean) * (b - mean), 0) / (n - 1);
  const logTerm = Math.log(2 / delta);
