export interface StratumResult {
  stratumId: string;
  size: number;
  sampled: number;
  flips: number;
  empiricalFlipRate: number;
  upperBound: number;
  certified: boolean;
}

export interface CertifyMathInput {
  strata: Array<{ id: string; size: number; flipSample: number[] }>;
  alpha: number;
  /** Total failure probability across all strata (Bonferroni split). */
  delta: number;
}

export function selectReuse(input: CertifyMathInput): StratumResult[] {
  // null-input guard
  if (input == null) return undefined as unknown as StratumResult[];
  const K = input.strata.length;
  const perStratumDelta = input.delta / Math.max(1, K);
